<script setup>
import { onMounted, ref } from 'vue'
import ListView from '../shared/components/ListView.vue'

const props = defineProps({ token: { type: String, required: true } })
const tab = ref('users'); const loading = ref(true); const saving = ref(false); const error = ref(''); const notice = ref('')
const users = ref([]); const roles = ref([]); const permissions = ref([])
const userPage = ref({ page: 1, pageSize: 10, totalItems: 0, totalPages: 1 }); const rolePage = ref({ page: 1, pageSize: 10, totalItems: 0, totalPages: 1 })
const userFormOpen = ref(false); const roleFormOpen = ref(false)
const editingUserId = ref(''); const editingRoleId = ref('')
const userForm = ref({ fullName: '', email: '', password: '', roleName: '' }); const roleForm = ref({ name: '', label: '', permissions: [] })

async function request(url, options = {}) { const response = await fetch(url, { ...options, headers: { Authorization: `Bearer ${props.token}`, ...(options.headers || {}) } }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || 'No se pudo completar la operación.'); return data }
async function loadUsers() { const params = new URLSearchParams({ page: String(userPage.value.page), pageSize: String(userPage.value.pageSize) }); const data = await request(`/api/app/security/users?${params}`); users.value = data.items || []; userPage.value = data.pagination || userPage.value }
async function loadRoles() { const params = new URLSearchParams({ page: String(rolePage.value.page), pageSize: String(rolePage.value.pageSize) }); const data = await request(`/api/app/security/roles?${params}`); roles.value = data.items || []; rolePage.value = data.pagination || rolePage.value; permissions.value = data.permissions || permissions.value }
async function load() { loading.value = true; error.value = ''; try { await Promise.all([loadUsers(), loadRoles()]) } catch (loadError) { error.value = loadError.message } finally { loading.value = false } }
async function saveUser() { saving.value = true; error.value = ''; try { const id = editingUserId.value; await request(id ? `/api/app/security/users/${id}` : '/api/app/security/users', { method: id ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(userForm.value) }); notice.value = id ? 'Usuario actualizado correctamente.' : 'Usuario creado correctamente.'; userForm.value = { fullName: '', email: '', password: '', roleName: '' }; editingUserId.value = ''; userFormOpen.value = false; await loadUsers() } catch (saveError) { error.value = saveError.message } finally { saving.value = false } }
async function saveRole() { saving.value = true; error.value = ''; try { const id = editingRoleId.value; await request(id ? `/api/app/security/roles/${id}` : '/api/app/security/roles', { method: id ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(roleForm.value) }); notice.value = id ? 'Rol actualizado correctamente.' : 'Rol creado correctamente.'; roleForm.value = { name: '', label: '', permissions: [] }; editingRoleId.value = ''; roleFormOpen.value = false; await loadRoles() } catch (saveError) { error.value = saveError.message } finally { saving.value = false } }
function editUser(item) { editingUserId.value = item.id; userFormOpen.value = true; userForm.value = { fullName: item.fullName, email: item.email, password: '', roleName: item.roles[0] || '' } }
function editRole(item) { editingRoleId.value = item.id; roleFormOpen.value = true; roleForm.value = { name: item.name, label: item.label, permissions: [...item.permissions] } }
function cancelUserForm() { userFormOpen.value = false; editingUserId.value = ''; userForm.value = { fullName: '', email: '', password: '', roleName: '' } }
function cancelRoleForm() { roleFormOpen.value = false; editingRoleId.value = ''; roleForm.value = { name: '', label: '', permissions: [] } }
async function removeUser(item) { if (!window.confirm(`¿Desactivar al usuario ${item.fullName}?`)) return; try { await request(`/api/app/security/users/${item.id}`, { method: 'DELETE' }); notice.value = 'Usuario desactivado.'; await loadUsers() } catch (removeError) { error.value = removeError.message } }
async function removeRole(item) { if (!window.confirm(`¿Eliminar el rol ${item.label}? Esta acción no se puede deshacer.`)) return; try { await request(`/api/app/security/roles/${item.id}`, { method: 'DELETE' }); notice.value = 'Rol eliminado.'; await loadRoles() } catch (removeError) { error.value = removeError.message } }
function page(kind, value) { const target = kind === 'users' ? userPage : rolePage; if (value < 1 || value > target.value.totalPages) return; target.value.page = value; kind === 'users' ? loadUsers() : loadRoles() }
onMounted(load)
</script>

<template>
  <section class="module-view security-view"><div class="module-heading"><div><p class="eyebrow">Control de acceso</p><h1>Usuarios y roles</h1><p>Administra quién puede entrar y qué módulos puede consultar.</p></div><button type="button" class="secondary-button compact" @click="load">↻ Actualizar</button></div><div class="security-tabs"><button type="button" :class="{ active: tab === 'users' }" @click="tab = 'users'">Usuarios <span>{{ userPage.totalItems }}</span></button><button type="button" :class="{ active: tab === 'roles' }" @click="tab = 'roles'">Roles <span>{{ rolePage.totalItems }}</span></button></div><p v-if="notice" class="security-notice">{{ notice }}</p><p v-if="error" class="request-error">{{ error }}</p><div v-if="loading" class="module-state panel">Cargando seguridad…</div>
    <ListView v-else-if="tab === 'users'" title="Usuarios registrados" description="Accesos vigentes en la plataforma." :count="userPage.totalItems" :page="userPage.page" :total-pages="userPage.totalPages" :empty="!users.length" empty-text="No hay usuarios registrados." @previous="page('users', userPage.page - 1)" @next="page('users', userPage.page + 1)"><template #actions><button type="button" class="primary-button compact" @click="userFormOpen = !userFormOpen; editingUserId = ''">+ {{ editingUserId ? 'Editar usuario' : 'Crear usuario' }}</button></template><template #toolbar><form v-if="userFormOpen" class="security-inline-form" @submit.prevent="saveUser"><input v-model="userForm.fullName" placeholder="Nombre completo" required /><input v-model="userForm.email" type="email" placeholder="Correo" required /><input v-if="!editingUserId" v-model="userForm.password" type="password" minlength="10" placeholder="Contraseña temporal" required /><select v-model="userForm.roleName" required><option value="" disabled>Rol</option><option v-for="role in roles" :key="role.name" :value="role.name">{{ role.label }}</option></select><button type="submit" class="primary-button compact" :disabled="saving">{{ editingUserId ? 'Actualizar' : 'Guardar' }}</button></form></template><template #columns><th>Usuario</th><th>Correo</th><th>Roles</th><th>Estado</th><th>Acciones</th></template><template #rows><tr v-for="item in users" :key="item.id"><td><div class="table-person"><span class="avatar avatar-table">{{ item.fullName.slice(0, 2).toUpperCase() }}</span><strong>{{ item.fullName }}</strong></div></td><td>{{ item.email }}</td><td>{{ item.roles.join(' · ') || 'Sin rol' }}</td><td><span :class="['security-status', { inactive: !item.active }]">{{ item.active ? 'Activo' : 'Inactivo' }}</span></td><td><button type="button" class="secondary-button compact" @click="editUser(item)">Editar</button> <button v-if="item.active" type="button" class="danger-link" @click="removeUser(item)">Desactivar</button></td></tr></template></ListView>
    <ListView v-else title="Roles disponibles" description="Perfiles que pueden asignarse a los usuarios." :count="rolePage.totalItems" :page="rolePage.page" :total-pages="rolePage.totalPages" :empty="!roles.length" empty-text="No hay roles registrados." @previous="page('roles', rolePage.page - 1)" @next="page('roles', rolePage.page + 1)"><template #actions><button type="button" class="primary-button compact" @click="roleFormOpen = !roleFormOpen; editingRoleId = ''">+ Crear rol</button></template><template #toolbar><form v-if="roleFormOpen" class="security-inline-form role-inline-form" @submit.prevent="saveRole"><input v-model="roleForm.name" placeholder="Identificador" pattern="[a-z][a-z0-9_-]{2,40}" :disabled="Boolean(editingRoleId)" required /><input v-model="roleForm.label" placeholder="Nombre visible" required /><div class="inline-permissions"><label v-for="permission in permissions" :key="permission.code"><input v-model="roleForm.permissions" type="checkbox" :value="permission.code" />{{ permission.label }}</label></div><button type="submit" class="primary-button compact" :disabled="saving">{{ editingRoleId ? 'Actualizar' : 'Guardar' }}</button></form></template><template #columns><th>Rol</th><th>Identificador</th><th>Permisos</th><th>Creado</th><th>Acciones</th></template><template #rows><tr v-for="item in roles" :key="item.id"><td><strong>{{ item.label }}</strong></td><td>{{ item.name }}</td><td><span class="count-badge">{{ item.permissions.length }}</span></td><td>{{ new Date(item.createdAt).toLocaleDateString('es-CO') }}</td><td><button type="button" class="secondary-button compact" @click="editRole(item)">Editar</button> <button type="button" class="danger-link" @click="removeRole(item)">Eliminar</button></td></tr></template></ListView>
    <div v-if="userFormOpen || roleFormOpen" class="security-cancel-bar"><button v-if="userFormOpen" type="button" class="secondary-button compact" @click="cancelUserForm">Cancelar usuario</button><button v-if="roleFormOpen" type="button" class="secondary-button compact" @click="cancelRoleForm">Cancelar rol</button></div>
  </section>
</template>

<style scoped>
.security-inline-form{display:grid;grid-template-columns:1fr 1fr 1fr 180px auto;gap:8px;padding:12px;border:1px solid #e5eaf0;border-radius:8px;background:#f8fafc}.security-inline-form input,.security-inline-form select{min-height:35px;padding:0 9px;border:1px solid #d8e0ea;border-radius:6px;color:#344b60;background:#fff;font-size:10px}.role-inline-form{grid-template-columns:1fr 1fr auto}.inline-permissions{display:flex;align-items:center;flex-wrap:wrap;gap:8px;grid-column:1/-1;padding-top:4px;color:#526174;font-size:9px}.inline-permissions label{display:flex;gap:4px;align-items:center}.danger-link{padding:0;border:0;color:#b54747;background:transparent;font-size:10px;font-weight:800;cursor:pointer}.danger-link:hover{text-decoration:underline}@media(max-width:800px){.security-inline-form,.role-inline-form{grid-template-columns:1fr}.inline-permissions{grid-column:auto}}
.security-cancel-bar{display:flex;justify-content:flex-end;gap:8px;margin-top:10px}
</style>
